29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Digits(fraction = 0, integer = 10)
51	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "membership_number")
62	    private Integer membershipNumber;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "membership_tier")
68	    private String membershipTier;
69	
70	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
71	    private Set<Pet> pets;
72	
73	    public String getAddress() {
74	        return this.address;
75	    }
76	
77	    public void setAddress(String address) {
78	        this.address = address;
79	    }
80	
81	    public String getCity() {
82	        return this.city;
83	    }
84	
85	    public void setCity(String city) {
86	        this.city = city;
87	    }
88	
89	    public String getTelephone() {
90	        return this.telephone;
91	    }
92	
93	    public void setTelephone(String telephone) {
94	        // Store telephone numbers as digits only, stripping spaces, dashes and
95	        // parentheses so that formatted input such as "(613) 555-0100" is kept
96	        // and compared as "6135550100".
97	        this.telephone = telephone == null ? null : telephone.replaceAll("[\\s()-]", "");
98	    }
99	
100	    public String getEmail() {
101	        return this.email;
102	    }
103	
104	    public void setEmail(String email) {
105	        this.email = email;
106	    }
107	
108	    public LocalDate getRegistrationDate() {
109	        return this.registrationDate;
110	    }
111	
112	    public void setRegistrationDate(LocalDate registrationDate) {
113	        this.registrationDate = registrationDate;
114	    }
115	
116	    public Integer getMembershipNumber() {
117	        return this.membershipNumber;
118	    }
119	
120	    public void setMembershipNumber(Integer membershipNumber) {
121	        this.membershipNumber = membershipNumber;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    public String getMembershipTier() {
133	        return this.membershipTier;
134	    }
135	
136	    public void setMembershipTier(String membershipTier) {
137	        this.membershipTier = membershipTier;
138	    }
139	
140	    protected Set<Pet> getPetsInternal() {
141	        if (this.pets == null) {
142	            this.pets = new HashSet<>();
143	        }
144	        return this.pets;
145	    }
146	
147	    protected void setPetsInternal(Set<Pet> pets) {
148	        this.pets = pets;
149	    }
150	
151	    public List<Pet> getPets() {
152	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
153	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
154	        return Collections.unmodifiableList(sortedPets);
155	    }
156	
157	    public void setPets(List<Pet> pets) {
158	        this.pets = new HashSet<>(pets);
159	    }
160	
161	    public void addPet(Pet pet) {
162	        getPetsInternal().add(pet);
163	        pet.setOwner(this);
164	    }
165	
166	    /**
167	     * Return the Pet with the given name, or null if none found for this Owner.
168	     *
169	     * @param name to test
170	     * @return true if pet name is already in use
171	     */
172	    public Pet getPet(String name) {
173	        return getPet(name, false);
174	    }
175	
176	    /**
177	     * Return the Pet with the given name, or null if none found for this Owner.
178	     *
179	     * @param name to test
180	     * @return true if pet name is already in use
181	     */
182	    public Pet getPet(String name, boolean ignoreNew) {
183	        name = name.toLowerCase();
184	        for (Pet pet : getPetsInternal()) {
185	            if (!ignoreNew || !pet.isNew()) {
186	                String compName = pet.getName();
187	                compName = compName.toLowerCase();
188	                if (compName.equals(name)) {
189	                    return pet;
190	                }
191	            }
192	        }
193	        return null;
194	    }
195	
196	    public Pet getPet(Integer petId) {
197	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
198	    }
199	
200	    @Override
201	    public String toString() {
202	        return new ToStringCreator(this)
203	
204	            .append("id", this.getId())
205	            .append("new", this.isNew())
206	            .append("lastName", this.getLastName())
207	            .append("firstName", this.getFirstName())
208	            .append("address", this.address)
209	            .append("city", this.city)
210	            .append("telephone", this.telephone)
211	            .toString();
212	    }
213	}
