17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        owner.setCity(resolveCity(owner.getCity()));
105	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
106	        owner.setCustomerCode(buildCustomerCode(owner.getCity()));
107	        owner.setMembershipTier(resolveMembershipTier());
108	        this.clinicService.saveOwner(owner);
109	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
110	        headers.setLocation(UriComponentsBuilder.newInstance()
111	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
112	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
113	    }
114	
115	    /**
116	     * Resolve the city for a newly created owner. If an owner already exists in
117	     * that city (matched case-insensitively), reuse that owner's exact spelling;
118	     * otherwise the supplied city is title-cased.
119	     */
120	    private String resolveCity(String city) {
121	        if (city == null) {
122	            return null;
123	        }
124	        return this.clinicService.findAllOwners().stream()
125	            .map(Owner::getCity)
126	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
127	            .findFirst()
128	            .orElseGet(() -> titleCase(city));
129	    }
130	
131	    /**
132	     * Title-case a city name: the first letter of each whitespace-separated word
133	     * is upper-cased and the remaining letters lower-cased.
134	     */
135	    private String titleCase(String city) {
136	        StringBuilder sb = new StringBuilder(city.length());
137	        boolean startOfWord = true;
138	        for (int i = 0; i < city.length(); i++) {
139	            char c = city.charAt(i);
140	            if (Character.isWhitespace(c)) {
141	                startOfWord = true;
142	                sb.append(c);
143	            } else if (startOfWord) {
144	                sb.append(Character.toUpperCase(c));
145	                startOfWord = false;
146	            } else {
147	                sb.append(Character.toLowerCase(c));
148	            }
149	        }
150	        return sb.toString();
151	    }
152	
153	    /**
154	     * The number of owners that, once created, are granted the 'FOUNDING'
155	     * membership tier. Owners created after this threshold receive 'STANDARD'.
156	     */
157	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
158	
159	    /**
160	     * Resolve the membership tier for a newly created owner: the first
161	     * {@link #FOUNDING_MEMBERSHIP_LIMIT} owners ever created are 'FOUNDING' and
162	     * all later owners are 'STANDARD'.
163	     */
164	    private String resolveMembershipTier() {
165	        long existingOwners = this.clinicService.findAllOwners().size();
166	        return existingOwners < FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD";
167	    }
168	
169	    /**
170	     * Build the customer code for a newly created owner, formatted as
171	     * '<UPPERCASE_CITY>-<NNNN>' where NNNN is one more than the number of owners
172	     * that already exist in that city, zero-padded to four digits.
173	     */
174	    private String buildCustomerCode(String city) {
175	        long ownersInCity = this.clinicService.findAllOwners().stream()
176	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
177	            .count();
178	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        currentOwner.setAddress(ownerFieldsDto.getAddress());
189	        currentOwner.setCity(ownerFieldsDto.getCity());
190	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
191	        currentOwner.setLastName(ownerFieldsDto.getLastName());
192	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
193	        currentOwner.setEmail(ownerFieldsDto.getEmail());
194	        this.clinicService.saveOwner(currentOwner);
195	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
